p-write-promisify-from-scratch.starter:
type Callback<T> = (err: Error | null | undefined, result?: T) => void;

/** Wrap an error-first callback function: same arguments minus the callback, returns a promise.
 *  Keep `this`, settle only once, and turn a synchronous throw into a rejection. */
function promisify<A extends unknown[], T>(fn: (...args: [...A, Callback<T>]) => void): (...args: A) => Promise<T> {
  throw new Error('Not implemented');
}

p-write-promisify-from-scratch.solution:
type Callback<T> = (err: Error | null | undefined, result?: T) => void;
function promisify<A extends unknown[], T>(fn: (...args: [...A, Callback<T>]) => void) {
  return function (this: unknown, ...args: A): Promise<T> {
    return new Promise<T>((resolve, reject) => {
      fn.call(this, ...args, (err: Error | null | undefined, result?: T) => {
        if (err) reject(err);
        else resolve(result as T);
      });
    });
  };
}

