p-once-with-a-timeout-and-a-signal.starter:
import { EventEmitter } from 'node:events';

/** Resolve with the arguments of the next `event`; reject on 'error', after timeoutMs, or when signal aborts
 *  (with signal.reason). In every case remove the listeners and timers you added. */
function waitFor(
  emitter: EventEmitter,
  event: string,
  { timeoutMs, signal }: { timeoutMs: number; signal?: AbortSignal },
): Promise<unknown[]> {
  throw new Error('Not implemented');
}

p-once-with-a-timeout-and-a-signal.solution:
import { EventEmitter } from 'node:events';
function waitFor(
  emitter: EventEmitter,
  event: string,
  { timeoutMs, signal }: { timeoutMs: number; signal?: AbortSignal },
): Promise<unknown[]> {
  return new Promise((resolve, reject) => {
    if (signal?.aborted) return reject(signal.reason);
    const onEvent = (...args: unknown[]) => {
      cleanup();
      resolve(args);
    };
    const onError = (err: unknown) => {
      cleanup();
      reject(err);
    };
    const onAbort = () => {
      cleanup();
      reject(signal?.reason);
    };
    const timer = setTimeout(() => {
      cleanup();
      reject(new Error(`timed out waiting for ${event}`));
    }, timeoutMs);
    function cleanup() {
      clearTimeout(timer);
      emitter.off(event, onEvent);
      emitter.off('error', onError);
      signal?.removeEventListener('abort', onAbort);
    }
    emitter.on(event, onEvent);
    emitter.on('error', onError);
    signal?.addEventListener('abort', onAbort, { once: true });
  });
}

